using System.ComponentModel.DataAnnotations;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.AspNetCore.Mvc.Rendering;using Microsoft.EntityFrameworkCore;using NoryMusicLMS_VS.Data;using NoryMusicLMS_VS.Models;using NoryMusicLMS_VS.Services;
namespace NoryMusicLMS_VS.Areas.Admin.Pages.Lessons;
[Authorize(Roles="Admin")] public class EditModel:PageModel{private readonly ApplicationDbContext _db;private readonly ImageStorageService _images;public EditModel(ApplicationDbContext db,ImageStorageService images){_db=db;_images=images;}[BindProperty]public LessonInput Input{get;set;}=new();public int LessonId{get;private set;}public string CourseTitle{get;private set;}="";public string? CurrentImageUrl{get;private set;}public class LessonInput{[Required]public int CourseId{get;set;}[Required,StringLength(100)]public string Title{get;set;}="";[StringLength(2000)]public string Content{get;set;}="";[Range(1,1000)]public int OrderIndex{get;set;}[Url]public string? VideoUrl{get;set;}[Url]public string? AudioUrl{get;set;}[Url]public string? NotationUrl{get;set;}public IFormFile? Image{get;set;}public bool RemoveImage{get;set;}}
public async Task<IActionResult> OnGetAsync(int id){var l=await _db.Lessons.Include(x=>x.Course).FirstOrDefaultAsync(x=>x.Id==id);if(l is null)return NotFound();Set(l);await LoadCoursesAsync();return Page();}
public async Task<IActionResult> OnPostAsync(int id){var l=await _db.Lessons.Include(x=>x.Course).FirstOrDefaultAsync(x=>x.Id==id);if(l is null)return NotFound();Set(l);if(!await _db.Courses.AnyAsync(c=>c.Id==Input.CourseId&&c.IsActive))ModelState.AddModelError("Input.CourseId","Select an active course.");if(ImageStorageService.Validate(Input.Image) is{ }e)ModelState.AddModelError("Input.Image",e);if(!ModelState.IsValid){await LoadCoursesAsync();return Page();}l.CourseId=Input.CourseId;l.Title=Input.Title.Trim();l.Content=Input.Content.Trim();l.OrderIndex=Input.OrderIndex;l.VideoUrl=Input.VideoUrl;l.AudioUrl=Input.AudioUrl;l.NotationUrl=Input.NotationUrl;l.ImageUrl=await _images.ApplyAsync(l.ImageUrl,Input.Image,Input.RemoveImage,null);await _db.SaveChangesAsync();TempData["StatusMessage"]="Lesson updated.";return RedirectToPage("./Index");}
private void Set(Lesson l){LessonId=l.Id;CourseTitle=l.Course.Title;CurrentImageUrl=l.ImageUrl;if(Input.Title=="")Input=new(){CourseId=l.CourseId,Title=l.Title,Content=l.Content,OrderIndex=l.OrderIndex,VideoUrl=l.VideoUrl,AudioUrl=l.AudioUrl,NotationUrl=l.NotationUrl};}private async Task LoadCoursesAsync()=>ViewData["CourseId"]=new SelectList(await _db.Courses.Where(c=>c.IsActive).OrderBy(c=>c.Title).ToListAsync(),"Id","Title",Input.CourseId);}
